            using var navApi=new OrdersFake();using var main=new MainForm(navApi,await navApi.ReadinessAsync());main.Show();using var timer=new System.Windows.Forms.Timer{Interval=60};var opened=false;timer.Tick+=(_,_)=>{var list=Application.OpenForms.OfType<OrderListForm>().FirstOrDefault();if(list is null||list.Grid.Rows.Count==0)return;opened=true;timer.Stop();list.Close();};timer.Start();main.Navigation.Single(b=>b.Text=="Đơn hàng").PerformClick();Assert(opened,"Main order navigation not connected");main.Close();
