                form.ReasonBox.Text="Lý do QA";api.WriteError=new AdminApiException("INVALID_STATE",409);foreach(var action in form.ActionButtons.Keys.Where(a=>a!=OrderAction.Invoice&&!actions.Contains(a))){var writes=api.Writes;await form.ActAsync(action);Assert(api.Writes==writes+1&&form.MessageLabel.Text.Contains("Trạng thái đã thay đổi")&&form.Current?.Status==state,"Forced invalid action not reported/refreshed");}form.Close();
