            using var failedApi=new OrdersFake{Row=OrdersFake.Order("DANG_GIAO")};using var failed=new OrderDetailForm(failedApi,33,(_,_)=>true);failed.Show();await Task.Delay(40);await failed.ActAsync(OrderAction.Fail);Assert(failedApi.Writes==0&&failed.ReasonErrorLabel.Text.Contains("lý do"),"Failure reason optional");failed.Close();
        });
        await Test("WIN.A19.04 stale409 auto-refresh, failed readback locks actions, unknown result retains intention",async()=>
        {
            using var api=new OrdersFake();using var form=new OrderDetailForm(api,33,(_,_)=>true);form.Show();await Task.Delay(50);api.Conflict=true;form.ReasonBox.Text="Lý do cần giữ QA";await form.ActAsync(OrderAction.Confirm);Assert(form.Current is{Status:"DA_HUY"}&&form.MessageLabel.Text.Contains("vui lòng tải lại")&&form.ReasonBox.Text=="Lý do cần giữ QA"&&!form.ActionButtons[OrderAction.Confirm].Visible,"Conflict did not refresh cancelled order");await Capture(form,"UI11-customer-conflict-refreshed");form.Close();
            using(var readApi=new OrdersFake{FailReadback=true}){using var readForm=new OrderDetailForm(readApi,33,(_,_)=>true);readForm.Show();await Task.Delay(50);await readForm.ActAsync(OrderAction.Confirm);Assert(!readForm.ActionButtons[OrderAction.Confirm].Enabled&&readForm.MessageLabel.Text.Contains("chưa sẵn sàng"),"Failed post-write GET not guarded");await readForm.LoadAsync();Assert(readForm.Current is null&&readForm.ActionButtons.Values.All(b=>!b.Visible),"Failed refresh retains actionable stale state");readApi.ReadError=null;await readForm.LoadAsync();Assert(readForm.Current is{Status:"DA_XAC_NHAN"}&&readApi.Writes==1,"Failed readback repeated command");readForm.Close();}
            using var lostApi=new OrdersFake();using var lost=new OrderDetailForm(lostApi,33,(_,_)=>true);lost.Show();await Task.Delay(50);lostApi.Lose=true;await lost.ActAsync(OrderAction.Confirm);var key=lost.OperationKey;var writes=lostApi.Writes;Assert(!lost.ActionButtons[OrderAction.Confirm].Enabled,"Unknown write not locked");await lost.LoadAsync();Assert(lost.Current is{Status:"DA_XAC_NHAN"}&&lost.OperationKey==key&&lostApi.Writes==writes,"Unknown reply blindly resent");lost.Close();
        });
        await Test("WIN.A21.01/02/03 invoice notice/snapshot and no-installed-printer/driver faults are recoverable on CI",async()=>
        {
            using var api=new OrdersFake{Row=OrdersFake.Order("HOAN_TAT")};var none=new TestPrinter();using(var form=new InvoiceForm(api,33,none)){form.Show();await Task.Delay(50);Assert(form.Current is not null&&form.ContentBox.ReadOnly&&form.NoticeLabel.Text==OrdersFake.Notice&&form.ContentBox.Text.Contains("24.000.000 đ"),"Invoice notice/snapshot absent");await Capture(form,"invoice-view");var writes=api.Writes;form.PreviewButton.PerformClick();Assert(none.Calls==0&&form.MessageLabel.Text.Contains("Chưa có máy in")&&form.ContentBox.Text.Contains(OrdersFake.Notice)&&api.Writes==writes,"No-driver preview failed or changed order");await Capture(form,"PrintPreview-no-installed-printer");form.Close();}
            using(var form=new InvoiceForm(api,33,new TestPrinter{Available=true,Throw=true})){form.Show();await Task.Delay(40);form.Preview();Assert(form.MessageLabel.Text.Contains("Kiểm tra máy in")&&form.Current is not null,"Driver failure crashed or erased invoice");form.Close();}
            api.Row=OrdersFake.Order("DA_HUY");using var denied=new InvoiceForm(api,33,none);denied.Show();await Task.Delay(40);Assert(denied.Current is null&&!denied.PreviewButton.Enabled&&denied.MessageLabel.Text.Contains("Trạng thái"),"Forbidden invoice fabricated");denied.Close();
        });
        await Test("WIN.A09.02/A12.01 actual customer drilldown opens full order detail from production handoff",async()=>
        {
            using var api=new OrdersFake();using var customer=new CustomerDetailsForm(api,1);customer.Show();await Task.Delay(50);using var timer=new System.Windows.Forms.Timer{Interval=80};var clicked=false;var full=false;timer.Tick+=async(_,_)=>{var detail=Application.OpenForms.OfType<OrderDetailForm>().FirstOrDefault();if(detail is not null&&detail.Current is not null){timer.Stop();full=detail.HistoryGrid.Rows.Count>0&&detail.ActionButtons[OrderAction.Confirm].Visible;await Capture(detail,"customer-to-full-order");detail.Close();Application.OpenForms.OfType<CustomerOrdersForm>().First().Close();return;}var orders=Application.OpenForms.OfType<CustomerOrdersForm>().FirstOrDefault();if(!clicked&&orders?.Grid.Rows.Count>0){clicked=true;orders.DetailsButton.PerformClick();}};timer.Start();customer.OrdersButton.PerformClick();Assert(full&&api.Writes==0,"Customer handoff did not reach full read-only-loaded detail");customer.Close();
        });
        File.WriteAllText(Path.Combine(output,"results.json"),System.Text.Json.JsonSerializer.Serialize(new{fakeApi=true,qaOnly=true,checks=passed-start,captures=captures.Skip(captureOffset).ToArray()},new System.Text.Json.JsonSerializerOptions{WriteIndented=true}));output=previous;Console.WriteLine($"{passed-start} admin W5 form checks passed.");
    }
    private sealed class TestPrinter:IInvoicePrinter{public bool Available,Throw;public int Calls;public bool HasInstalledPrinter=>Available;public void Preview(IWin32Window owner,AdminInvoice invoice){Calls++;if(Throw)throw new InvalidOperationException("QA driver unavailable");}}
