internal sealed class OrdersFake:IAdminApi
{
    public const string Version="AQAAAAAAAAA=";public const string Notice="Chứng từ bán hàng nội bộ; không phải hóa đơn điện tử thuế.";
    public static AdminOrder Order(string state="CHO_XAC_NHAN")=>new(33,"W5-ORDER-QA",1,"Người nhận snapshot QA","0938123591","Địa chỉ snapshot QA",state,state=="HOAN_TAT"?"DA_THU":"CHUA_THU",24000000,DateTimeOffset.UtcNow,state=="HOAN_TAT"?DateTimeOffset.UtcNow:null,Version,false,[new(3,"Điện thoại snapshot QA","QA-W5-A","Đen ·128 GB",2,12000000,24000000)],[new(1,null,state,90,"admin-qa",DateTimeOffset.UtcNow,"Lịch sử QA")]);
    public AdminOrder Row=Order();public int Writes;public List<string> Paths { get; }=[];public bool Empty,Conflict,Lose,FailReadback;public TaskCompletionSource? HoldRead,HoldWrite;public Exception? ReadError,WriteError;public OrderCommand? LastCommand;public bool NeedsReconciliation { get; private set; }
    public AdminIdentity? Identity=>new(90,"admin-qa","ADMIN",DateTimeOffset.UtcNow.AddHours(8));public event Action? SessionEnded{add{}remove{}}
    public async Task<T> GetAsync<T>(string path,CancellationToken ct=default)
    {
        Paths.Add(path);if(HoldRead is not null)await HoldRead.Task.WaitAsync(ct);if(ReadError is not null)throw ReadError;object result;
        if(path.EndsWith("/invoice")){if(!OrderPresentation.Allowed(Row.Status,Row.ReturnReceived,OrderAction.Invoice))throw new AdminApiException("INVALID_STATE",409);result=new AdminInvoice("HÓA ĐƠN BÁN HÀNG",Notice,Row);}
        else if(path.StartsWith("/api/admin/customers/1/orders?"))result=new PageResult<CustomerOrder>([new(Row.Id,Row.Code,1,Row.Recipient,Row.Phone,Row.Address,Row.Status,Row.Payment,Row.Total,Row.CreatedAt,Row.Lines.Select(x=>new OrderPeekLine(x.VariantId,x.Name,x.Sku,x.Description,x.Quantity,x.Price,x.Total)).ToList())],1,1,20);
        else if(path=="/api/admin/customers/1")result=new CustomerRecord(1,"customer-qa","Khách QA","0938123591",null,"QA",true,DateTimeOffset.UtcNow);
        else if(path.StartsWith("/api/admin/orders?"))result=new PageResult<AdminOrder>(Empty?[]:[Row],Empty?0:45,path.Contains("page=2&")?2:1,20);
        else if(path=="/api/admin/orders/33")result=Row;
        else throw new InvalidOperationException("Unexpected order fake route");return (T)result;
    }
    public async Task CommandAsync<T>(string path,T input,CommandIntent intent,CancellationToken ct=default)
    {
        Writes++;LastCommand=(OrderCommand)(object)input!;if(HoldWrite is not null)await HoldWrite.Task;if(Conflict){Conflict=false;Row=Row with{Status="DA_HUY",Version="AgAAAAAAAAA="};throw new AdminApiException("CONCURRENT_UPDATE",409);}if(WriteError is not null)throw WriteError;
        var status=path.Split('/').Last() switch{"confirm"=>"DA_XAC_NHAN","cancel"=>"DA_HUY","dispatch"=>"DANG_GIAO","complete"=>"HOAN_TAT",_=>"GIAO_THAT_BAI"};Row=Row with{Status=status,Payment=status=="HOAN_TAT"?"DA_THU":"CHUA_THU",CompletedAt=status=="HOAN_TAT"?DateTimeOffset.UtcNow:null,ReturnReceived=path.EndsWith("receive-return"),Version="AgAAAAAAAAA="};if(FailReadback){FailReadback=false;ReadError=new AdminApiException("DATABASE_UNAVAILABLE",503);}if(Lose){Lose=false;NeedsReconciliation=true;throw new AdminApiException("UNCERTAIN");}
    }
    public async Task ReconcileAsync(Func<CancellationToken,Task> read,CancellationToken ct=default){await read(ct);NeedsReconciliation=false;}
    public Task<ReadyInfo> ReadinessAsync(CancellationToken ct=default)=>Task.FromResult(new ReadyInfo("ready","QA · API giả","order-fixture-no-server"));public Task<AdminIdentity> LoginAsync(string u,string p,CancellationToken ct=default)=>Task.FromResult(Identity!);public Task<AdminIdentity?> RecoverSessionAsync(CancellationToken ct=default)=>Task.FromResult(Identity);public Task LogoutAsync(CancellationToken ct=default)=>Task.CompletedTask;public Task ChangePasswordAsync(string a,string b,CancellationToken ct=default)=>Task.CompletedTask;public void Dispose(){}
}
